// In an app: Array.prototype.last = last; then [1, 2, 3].last() === 3
function last(this: unknown[]): unknown {
  return this.length === 0 ? -1 : this[this.length - 1];
}

function lastItem(arr: unknown[]): unknown {
  return last.call(arr);
}

